/**
 * Worker entry: the OpenNext-built Next.js app plus the scheduled (cron) handler.
 * The cron trigger in wrangler.jsonc calls the app's own POST /api/sync/reconcile with the CRON_SECRET.
 */
// @ts-ignore: generated by `opennextjs-cloudflare build`
import handler from './.open-next/worker.js';

interface Env { CRON_SECRET?: string; [k: string]: unknown }

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.CRON_SECRET) return; // fail closed: no secret, no scheduled sync
    const req = new Request('https://internal.invalid/api/sync/reconcile', { method: 'POST', headers: { authorization: `Bearer ${env.CRON_SECRET}` } });
    ctx.waitUntil(handler.fetch(req, env, ctx));
  },
};

// @ts-ignore: durable objects used by OpenNext are re-exported when present
export * from './.open-next/worker.js';
